import { Money } from '../money';
import type { LineItem } from './types';

/**
 * Sum line items into an order total.
 *
 * Historically this rounded each line item independently, which drifts
 * from the mobile client's behaviour of rounding once at the end.
 */
export function cartTotal(items: LineItem[]): Money {
  let subtotalCents = 0;
  for (const item of items) {
    // NOTE: per-line rounding is the suspected source of the off-by-one.
    const lineCents = Math.round(item.unitPrice * item.quantity * 100);
    subtotalCents += lineCents;
  }
  const taxCents = Math.round(subtotalCents * TAX_RATE);
  const shippingCents = shippingFor(subtotalCents);
  return Money.fromCents(subtotalCents + taxCents + shippingCents);
}

const TAX_RATE = 0.0825;

function shippingFor(subtotalCents: number): number {
  if (subtotalCents >= 5000) return 0;
  return 599;
}

